@page "/"

<PageTitle>Recipe Community - Home</PageTitle>

<h1>Welcome to Recipe Community</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeCommunity.Models.RecipeStore.Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">
                        @RecipeCommunity.Models.RecipeStore.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="categories/@category" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Mexican" => "🇲🇽",
        "Thai" => "🇹🇭",
        "French" => "🇫🇷",
        _ => "🍽️"
    };
}

@page "/categories"
@page "/categories/{CategoryName}"
@using RecipeCommunity.Models

<PageTitle>Browse Recipes</PageTitle>

@if (string.IsNullOrEmpty(CategoryName))
{
    <h1>All Categories</h1>
    <div class="list-group mt-3">
        @foreach (var category in RecipeStore.Categories)
        {
            <a href="categories/@category" class="list-group-item list-group-item-action">
                <strong>@category</strong>
                <span class="badge bg-secondary float-end">@RecipeStore.GetByCategory(category).Count</span>
            </a>
        }
    </div>
}
else
{
    <h1>@CategoryName Recipes</h1>
    <a href="categories" class="btn btn-outline-secondary btn-sm mb-3">← All Categories</a>

    <div class="row">
        @foreach (var recipe in RecipeStore.GetByCategory(CategoryName))
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@(recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="categories" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <a href="categories/@recipe.Category" class="btn btn-outline-secondary btn-sm mb-3">← Back to @recipe.Category</a>

    <h1>@recipe.Title</h1>
    <span class="badge bg-info mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Instructions</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-4">
        <div class="card-body">
            <h5>Rate this Recipe</h5>
            <p class="text-muted">Current rating: ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
            <StarRating RecipeId="@recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@submission.Title</strong>" with the community.</p>
        <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="@submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Thai">Thai</option>
                <option value="French">French</option>
                <option value="American">American</option>
                <option value="Japanese">Japanese</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="submission.Ingredients"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs..." />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps"
                placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients..." />
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        var newId = RecipeStore.Recipes.Max(r => r.Id) + 1;
        RecipeStore.Recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
        submitted = true;
    }

    private void Reset()
    {
        submission = new();
        submitted = false;
    }
}

@using RecipeCommunity.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating ?? selectedRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = null"
              role="button">
            ★
        </span>
    }
    @if (selectedRating > 0)
    {
        <span class="ms-2 text-muted">You rated: @selectedRating/5</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.8rem;
        color: #ccc;
        cursor: pointer;
        transition: color 0.15s;
    }
    .star-rating .star.filled {
        color: #ffc107;
    }
    .star-rating .star:hover {
        transform: scale(1.2);
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private int? hoverRating;

    private void Rate(int stars)
    {
        selectedRating = stars;
        var recipe = RecipeStore.GetById(RecipeId);
        if (recipe is not null)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
        }
    }
}

